def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    day = day_context['day']
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if not alive:
        if hp <= 2 or no_water >= 2:
            return float(min(budget, DAILY_SALARY * 0.9))
        return float(min(budget, DAILY_SALARY * 0.25))

    prev_bids = []
    high_pressure_count = 0
    desperate_count = 0
    rich_count = 0
    for opp in alive:
        if opp.get('budget', 0) >= 300:
            rich_count += 1
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 2:
            desperate_count += 1
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
            if bid >= DAILY_SALARY * 0.9:
                high_pressure_count += 1

    max_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    severe_need = hp <= 2 or no_water >= 2
    moderate_need = hp <= 4 or no_water >= 1
    very_tight_supply = supply < WATER_REQ * 2
    tight_supply = supply <= 18

    if severe_need:
        target = max(DAILY_SALARY * 0.92, max_prev + 2.0)
        if very_tight_supply:
            target = max(target, DAILY_SALARY * 1.02)
        return float(min(budget, target))

    if moderate_need:
        target = max(DAILY_SALARY * 0.72, avg_prev + 3.0)
        if high_pressure_count >= 2 or desperate_count >= 2:
            target = max(target, DAILY_SALARY * 0.9)
        if very_tight_supply:
            target = max(target, DAILY_SALARY * 0.95)
        return float(min(budget, target))

    if very_tight_supply:
        if max_prev >= DAILY_SALARY * 0.95 or rich_count >= 2:
            return float(min(budget, DAILY_SALARY * 0.18))
        return float(min(budget, max(DAILY_SALARY * 0.45, avg_prev + 1.5)))

    if tight_supply:
        if high_pressure_count >= 2:
            return float(min(budget, DAILY_SALARY * 0.22))
        return float(min(budget, max(DAILY_SALARY * 0.35, avg_prev * 0.75 + 1.0)))

    if max_prev >= DAILY_SALARY * 1.0:
        return float(min(budget, DAILY_SALARY * 0.15))

    if day >= 8:
        return float(min(budget, DAILY_SALARY * 0.4))

    return float(min(budget, DAILY_SALARY * 0.28))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    hp = float(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opponents = []
    for oid, o in opponents_status.items():
        try:
            if o.get('alive', False):
                alive_opponents.append(o)
        except Exception:
            pass

    # If no opponents alive, conserve.
    if not alive_opponents:
        return float(min(budget, DAILY_SALARY * 0.4))

    # Read only yesterday's previous_trace bid.
    prev_bids = []
    for o in alive_opponents:
        pt = o.get('previous_trace', {}) or {}
        b = pt.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Heuristic: moderate bid baseline scales with supply pressure.
    # More supply reduces need to overbid.
    supply_factor = 1.0
    if supply <= 16.0:
        supply_factor = 1.15
    elif supply >= 22.0:
        supply_factor = 0.9

    # If we are at risk (no-water streak), bid more.
    risk_boost = 1.0
    if no_water_days >= 2:
        risk_boost = 1.25
    if hp <= 2:
        risk_boost = 1.45

    # React to opponents spending yesterday.
    # If they were near aggressive spending (> 0.75 salary), we compete a bit more.
    aggression = 1.0
    if highest_prev_bid >= DAILY_SALARY * 0.75:
        aggression = 1.12
    elif highest_prev_bid >= DAILY_SALARY * 0.6:
        aggression = 1.05

    # Target bid: keep below aggressive ceiling to avoid Cindy-like collapse.
    # Base around 0.55 salary, then adjust.
    base = DAILY_SALARY * 0.55
    target = base * supply_factor * risk_boost * aggression

    # If we are already healthy and not in streak, slightly lower.
    if hp >= 6 and no_water_days == 0:
        target *= 0.88

    # Ensure we don't exceed budget.
    bid = min(budget, target)

    # Also avoid bidding too low when hp is critical.
    if hp <= 2:
        bid = max(bid, min(budget, DAILY_SALARY * 0.85))

    # Final clamp to reasonable bounds.
    if bid < 0.0:
        bid = 0.0
    return float(bid)
